head.script:
scwin.screenId = "jldfil30409";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30409.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_register_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_register_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_register_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.register()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30409.btn_register_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_list_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_list_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_list_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.list()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30409.btn_list_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_list = async function () {
    const sbmOptions = {
        id: "tx_fn_list",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_listReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30409.tx_fn_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30409.tx_fn_register" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.frm || { elements: [] });
    scwin.form_frm.action = '/issue/IRroom.do';
    if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'irCenter') {
        $c.util.getComponent('dma_listReq').set('method', 'searchIRroomResv');
    } else {
        if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'mainMeetroom') {
            $c.util.getComponent('dma_listReq').set('method', 'searchMainMeetingroomResv');
        } else {
            if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'smartBzCenter') {
                $c.util.getComponent('dma_listReq').set('method', 'searchSmartBzCenterResv');
            } else {
                $c.util.getComponent('dma_listReq').set('method', "");
                await $c.win.alert('Market Square 목록 오류발생. 관리자에게 문의하세요.');
                return;
            }
        }
    }
    { const nr = await scwin.tx_fn_list(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30401/jldfil30401.xml", { "method": 'searchIRroomResv' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($("#ipt_perInfoChk").is(":checked") !== true) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해야 신청가능합니다.");
        $c.util.getComponent("ipt_perInfoChk").focus();
        return;
    }
    const frm = (document.frm || { elements: [] });
    scwin.form_frm.action = "/issue/IRroom.do";
    if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'irCenter') {
        $c.util.getComponent('dma_listReq').set('method', 'goIRroomResv');
    } else {
        if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'mainMeetroom') {
            $c.util.getComponent('dma_listReq').set('method', 'goMainMeetingroomResv');
        } else {
            if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'smartBzCenter') {
                $c.util.getComponent('dma_listReq').set('method', "goSmartBzCenterResv");
            } else {
                $c.util.getComponent('dma_listReq').set('method', "");
                await $c.win.alert('Market Square 동의 오류발생. 관리자에게 문의하세요.');
                return;
            }
        }
    }
    { const nr = await scwin.tx_fn_register(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30402/jldfil30402.xml", { "method": 'goIRroomResv' }); } };
    /* sdd-asis-lifecycle:end */
};
